@startuml

class Aircraft {
  + Name : string
  + Type : string
  + YearOfManufacture : int
  + NextInspectionDate : date
}

class PassengerAircraft extends Aircraft {
  + NumberOfSeats : int
}

class SeatCategory {
  + Designation : string
  + OffersEntertainment : boolean
  + NumberOfSeats : int
}

class Flight {
  + FlightNumber : string
  + Date : date
}

class Passenger {
  + Name : string
  + PassportNumber : string
}

class Ticket {
  + TicketNumber : string
  + Price : float
  + UpgradeDesired : boolean
}

class Airline {
  + Name : string
}

class Employee {
  + Name : string
  + DateOfEmployment : date
}

class FlightAttendant extends Employee {
  + IsChiefStewardess : boolean
}

class Pilot extends Employee {
  + License : string
}

class Airport {
  + Name : string
  + Address : string
  + RunwayCount : int
}

Aircraft "0..*" -- "0..1" Airline : belongs to
Aircraft "0..*" -- "0..1" Airport : home airport
Aircraft "1" -- "0..*" Flight : performs
Flight "1" -- "0..*" Ticket : has
Flight "1" -- "0..*" Passenger : involves
Passenger "1" -- "0..*" Ticket : holds
Ticket "0..*" -- "1" SeatCategory : for
SeatCategory "1" -- "0..*" PassengerAircraft : belongs to
Flight "1" -- "1" Airport : departs from
Flight "1" -- "1" Airport : arrives at
Flight "1" -- "0..*" FlightAttendant : staffed by
Flight "1" -- "1 Captain" Pilot : captained by
Flight "1" -- "1..2 Co-pilot" Pilot : co-piloted by
Airline "1" -- "0..*" FlightAttendant : employs
Airline "1" -- "0..*" Pilot : employs

@enduml

